Item.method_code:
const [{ odataFetch, getResource }, { alert }] =
	await Promise.all([
		import('../jsBundles/core.es.js'),
		import('../jsBundles/dialogs.es.js')
	]);

const item = options.item;

if (item.classification === 'Responsive') {
	await alert(getResource('item_methods.save_as_responsive_form_error'));
	return;
}

const requestURL = `FormComposite?$filter=source_id eq '${item.id}'&$count=true`;
const formCompositesRelatedToFormCount = await odataFetch(requestURL);

if (formCompositesRelatedToFormCount['@odata.count'] > 0) {
	await alert(getResource('item_methods.save_as_responsive_form_error'));
	return;
}

return commands.globalCommand.execute();
